// ============================================================
// CONFIGURE YOUR REMINDERS
// ============================================================
const CLIQ_WEBHOOK_URL = 'https://cliq.zoho.eu/company/YOUR_ORG/api/v2/channelsbyname/YOUR_CHANNEL/message';
// Alternative: use incoming webhook URL from Cliq channel settings
// const CLIQ_WEBHOOK_URL = 'https://cliq.zoho.eu/webhook?zapikey=YOUR_ZAPI_KEY';

const ZOHO_ACCESS_TOKEN_HEADER = true; // set false if using zapikey webhook
// ============================================================

const hour = new Date().getHours();
let message = '';

if (hour < 12) {
  message = 'Good morning team! Reminder: please check your open tickets and update statuses.';
} else {
  message = 'Afternoon check-in: please review any pending customer responses before EOD.';
}

return [{
  json: {
    webhookUrl: CLIQ_WEBHOOK_URL,
    message,
    useAuth: ZOHO_ACCESS_TOKEN_HEADER
  }
}];
